import React, { useEffect, useState } from 'react'
import {Link} from "react-router-dom";
import './Reports.css'
import axios from "axios";




export default function Reports() {
    const [user, setUser] = useState(null);
    const localUser = JSON.parse(localStorage.getItem('user'));

    const [userRole, setUserRole] = useState(null);
    const [accessData, setAccessData] = useState([]);

    useEffect(() => {
        const getUser = async () => {
            try {
                const response = await axios.get('/api/user/' + localUser._id);
                const roleId = response.data.role_id;
                setUserRole(roleId);

                // Запрашиваем разрешения только после того, как установили роль
                const res = await axios.get('/api/permission/' + roleId);
                setAccessData(res.data);

                // Устанавливаем пользователя
                setUser(response.data);

            } catch (error) {
                console.error('Error fetching user or permissions:', error);
            }
        };

        if (localUser) {
            getUser();
        }
    }, [localUser]);

    const isAccessible = (toolId) => {
        console.log('tol=',toolId)
        const access = accessData.find(item => item.toolId === toolId);
        return access ? access.is_accessible : false;
    };
    isAccessible()

    return (
        <div className="ReportsButton">
            {user === null ? (
                <div></div>
            ) : (
                <>
                    {userRole && isAccessible('someToolId') && ( // Укажите конкретный toolId
                        <Link to='/ReportsHistory' className='linkReports'>Отчет по истории</Link>
                    )}
                    <br />
                    {(user.role_id === '2' || user.role_id === '3' || user.role_id === '4') && (
                        <Link to='/ReportsNominations' className='linkReports'>Отчет по номинациям</Link>
                    )}
                </>
            )}
        </div>
    );
}
